AssistantMessageToolRequest(name='create', tool_call_id='function-call-dc06b0f1-a574-460d-a182-6cde80f8418e', arguments={'file_text': 'const { useState } = React;

const questions = [
  {
    id: 1,
    question: "Which of the following are statically typed languages?",
    helpText: "Select all that apply. Statically typed languages check types at compile-time.",
    options: ["Java", "Python", "C++", "JavaScript"]
  },
  {
    id: 2,
    question: "Which languages are primarily used for system programming?",
    options: ["Rust", "PHP", "C", "Ruby"]
  },
  {
    id: 3,
    question: "Which of these are considered functional programming languages?",
    options: ["Haskell", "Lisp", "Elixir", "C#"]
  }
];

const CheckboxGroup = ({ options, selectedOptions, onChange }) => {
  return (
    <div className="options-group">
      {options.map((option) => (
        <label key={option} className="option-label">
          <input
            type="checkbox"
            checked={selectedOptions.includes(option)}
            onChange={() => onChange(option)}
          />
          {option}
        </label>
      ))}
    </div>
  );
};

const Question = ({ data, selectedOptions, onOptionToggle }) => {
  return (
    <div className="form-field">
      <div className="question-text">{data.question}</div>
      {data.helpText && <div className="help-text">{data.helpText}</div>}
      <CheckboxGroup
        options={data.options}
        selectedOptions={selectedOptions}
        onChange={onOptionToggle}
      />
    </div>
  );
};

const Quiz = () => {
  const [selections, setSelections] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const handleToggle = (questionId, option) => {
    setSelections((prev) => {
      const currentSelections = prev[questionId] || [];
      if (currentSelections.includes(option)) {
        return {
          ...prev,
          [questionId]: currentSelections.filter((item) => item !== option),
        };
      } else {
        return {
          ...prev,
          [questionId]: [...currentSelections, option],
        };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    setSubmitted(true);
    console.log("Submitted Selections:", selections);
  };

  return (
    <div className="quiz-container">
      <h1>Computer Language Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map((q) => (
          <Question
            key={q.id}
            data={q}
            selectedOptions={selections[q.id] || []}
            onOptionToggle={(option) => handleToggle(q.id, option)}
          />
        ))}
        <button type="submit">Submit Quiz</button>
      </form>
      {submitted && (
        <div className="results">
          Thank you for completing the quiz! Check the console for your answers.
        </div>
      )}
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
