            font-weight: bold;
            cursor: pointer;
            transition: opacity 0.2s;
        }

        button:hover {
            opacity: 0.9;
        }

        .results {
            margin-top: 2rem;
            padding: 1rem;
            background-color: #2e7d32;
            color: white;
            border-radius: 6px;
            text-align: center;
        }
    </style>
</head>
<body>
    <div id="root"></div>
