            --accent-color: #bb86fc;
            --secondary-text: #b0b0b0;
            --border-color: #333;
            --hover-color: #2c2c2c;
        }

        body {
            background-color: var(--bg-color);
            color: var(--text-color);
            font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
            display: flex;
            justify-content: center;
            padding: 2rem;
            margin: 0;
        }

        #root {
            width: 100%;
            max-width: 600px;
        }

        .quiz-container {
            background-color: var(--card-bg);
            padding: 2rem;
            border-radius: 12px;
            box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
        }

        h1 {
            text-align: center;
            color: var(--accent-color);
            margin-bottom: 2rem;
        }

        .form-field {
            margin-bottom: 2rem;
            padding-bottom: 1.5rem;
            border-bottom: 1px solid var(--border-color);
        }

        .form-field:last-of-type {
            border-bottom: none;
        }

        .question-text {
            font-size: 1.2rem;
            font-weight: 600;
            margin-bottom: 0.5rem;
        }

        .help-text {
            font-size: 0.9rem;
            color: var(--secondary-text);
            margin-bottom: 1rem;
            font-style: italic;
        }

        .options-group {
            display: flex;
            flex-direction: column;
            gap: 0.75rem;
        }

        .option-label {
            display: flex;
            align-items: center;
            padding: 0.75rem;
            background-color: var(--hover-color);
            border-radius: 6px;
            cursor: pointer;
            transition: background-color 0.2s;
        }

        .option-label:hover {
            background-color: #383838;
        }

        .option-label input {
            margin-right: 1rem;
            width: 1.2rem;
            height: 1.2rem;
            accent-color: var(--accent-color);
        }

        button {
            width: 100%;
            padding: 1rem;
            background-color: var(--accent-color);
            color: #000;
            border: none;
            border-radius: 6px;
            font-size: 1.1rem;
            font-weight: bold;
            cursor: pointer;
            transition: opacity 0.2s;
        }

        button:hover {
            opacity: 0.9;
        }

        .results {
            margin-top: 2rem;
            padding: 1rem;
            background-color: #2e7d32;
            color: white;
            border-radius: 6px;
            text-align: center;
        }
    </style>
</head>
<body>
    <div id="root"></div>
    <script type="text/babel" data-presets="react">
        const { useState } = React;

        const questions = [
          {
            id: 1,
            question: "Which of the following are statically typed languages?",
            helpText: "Select all that apply. Statically typed languages check types at compile-time.",
            options: ["Java", "Python", "C++", "JavaScript"]
          },
          {
            id: 2,
            question: "Which languages are primarily used for system programming?",
            options: ["Rust", "PHP", "C", "Ruby"]
          },
          {
            id: 3,
            question: "Which of these are considered functional programming languages?",
            options: ["Haskell", "Lisp", "Elixir", "C#"]
          }
        ];

        const CheckboxGroup = ({ options, selectedOptions, onChange }) => {
          return (
            <div className="options-group">
              {options.map((option) => (
                <label key={option} className="option-label">
                  <input
                    type="checkbox"
                    checked={selectedOptions.includes(option)}
                    onChange={() => onChange(option)}
                  />
                  {option}
                </label>
              ))}
            </div>
          );
        };

        const Question = ({ data, selectedOptions, onOptionToggle }) => {
          return (
            <div className="form-field">
              <div className="question-text">{data.question}</div>
              {data.helpText && <div className="help-text">{data.helpText}</div>}
              <CheckboxGroup
                options={data.options}
                selectedOptions={selectedOptions}
                onChange={onOptionToggle}
              />
            </div>
          );
        };

        const Quiz = () => {
          const [selections, setSelections] = useState({});
          const [submitted, setSubmitted] = useState(false);

          const handleToggle = (questionId, option) => {
            setSelections((prev) => {
              const currentSelections = prev[questionId] || [];
              if (currentSelections.includes(option)) {
                return {
                  ...prev,
                  [questionId]: currentSelections.filter((item) => item !== option),
                };
              } else {
                return {
                  ...prev,
                  [questionId]: [...currentSelections, option],
                };
              }
            });
          };

          const handleSubmit = (e) => {
            e.preventDefault();
            setSubmitted(true);
            console.log("Submitted Selections:", selections);
          };

          return (
            <div className="quiz-container">
              <h1>Computer Language Quiz</h1>
              <form onSubmit={handleSubmit}>
                {questions.map((q) => (
                  <Question
                    key={q.id}
                    data={q}
                    selectedOptions={selections[q.id] || []}
                    onOptionToggle={(option) => handleToggle(q.id, option)}
                  />
                ))}
                <button type="submit">Submit Quiz</button>
              </form>
              {submitted && (
                <div className="results">
                  Thank you for completing the quiz! Check the console for your answers.
                </div>
              )}
            </div>
          );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<Quiz />);
    </script>
</body>
</html>
